<?php get_header(); $plans=woogit_plans(); $options=woogit_theme_options(); $features=woogit_theme_items('features_json',[['title'=>'اتصال امن','description'=>'احراز هویت و مالکیت سایت در Backend انجام می‌شود.','icon'=>'01','enabled'=>true],['title'=>'تجربه یکپارچه','description'=>'اطلاعات سرویس، اشتراک و حساب در یک Portal شفاف ارائه می‌شود.','icon'=>'02','enabled'=>true],['title'=>'طراحی سریع','description'=>'رابط سبک و responsive برای دسکتاپ و موبایل.','icon'=>'03','enabled'=>true]]); $steps=woogit_theme_items('steps_json',[['title'=>'فروشگاه را متصل کنید','description'=>'اطلاعات لازم را در مسیر امن Web Bootstrap وارد کنید.','enabled'=>true],['title'=>'حساب را تأیید کنید','description'=>'Backend هویت و مالکیت سایت را بررسی می‌کند.','enabled'=>true],['title'=>'سرویس را مدیریت کنید','description'=>'اشتراک، پرداخت و وضعیت سرویس را از پرتال دنبال کنید.','enabled'=>true]]); $heroImage=woogit_theme_image($options['hero_image_id']??0,'large'); ?>
